-- TrustCheck: MySQL 8.0.16+ / 8.4. Run this entire file.
-- Existing records are preserved. INSERT IGNORE skips existing primary keys.
CREATE DATABASE IF NOT EXISTS `trustcheck_local` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `trustcheck_local`;
SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE IF NOT EXISTS businesses (
 id INT PRIMARY KEY, name VARCHAR(120) NOT NULL,
 category VARCHAR(50) NOT NULL, city VARCHAR(80) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviewers (
 id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, joined DATE NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (
 id INT AUTO_INCREMENT PRIMARY KEY,
 business_id INT NOT NULL, reviewer_id INT NOT NULL,
 rating TINYINT NOT NULL, body TEXT NOT NULL, posted DATETIME(3) NOT NULL,
 status ENUM('Pending','Reviewed','Dismissed') NOT NULL DEFAULT 'Pending',
 CONSTRAINT chk_rating CHECK (rating BETWEEN 1 AND 5),
 CONSTRAINT fk_review_business FOREIGN KEY(business_id) REFERENCES businesses(id),
 CONSTRAINT fk_review_reviewer FOREIGN KEY(reviewer_id) REFERENCES reviewers(id),
 INDEX idx_business_time(business_id,posted), INDEX idx_reviewer(reviewer_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit (
 id INT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(255) NOT NULL, created DATETIME(3) NOT NULL
) ENGINE=InnoDB;
START TRANSACTION;

-- 8 businesses

-- 96 reviewers

-- 516 reviews

COMMIT;
SELECT 'businesses' AS table_name,COUNT(*) AS row_count FROM businesses UNION ALL SELECT 'reviewers',COUNT(*) FROM reviewers UNION ALL SELECT 'reviews',COUNT(*) FROM reviews;
